-- MathLabs V27.5 → V27.9 · 8B COMPLETE STAGING · CONSOLIDATED INSTALL
-- 17 OA · 34 topics · 136 nodes · deep content · 884 assessment items · adaptive · diagnostic · routes.
-- No publication controller. No live student delivery.
begin;
select public.mathlabs_assert_admin_v22();

do $$
declare
 v_course int; v_catalog int; v_existing int;
 v3items int; v3meta int; v3auto int;
 v3deep int; v3pub int; v4stage int; v4pub int; vqueue int;
 vp int; vd int; vr int; vs int; vrel int;
 v_calib_col int; v_origin_col int;
begin
 select count(*) into v_course from public.courses where id='cl-8-basico';
 if v_course<>1 then raise exception 'Preflight V27.5: cl-8-basico no existe en public.courses'; end if;

 if to_regclass('public.mathlabs_course_catalog_v259') is null then raise exception 'Falta V25.9'; end if;
 select count(*) into v_catalog from public.mathlabs_course_catalog_v259 where course_id='cl-8-basico';
 if v_catalog<>1 then raise exception '8B no está registrado en V25.9'; end if;

 if to_regclass('public.multigrade_assessment_items_v261') is null
    or to_regclass('public.multigrade_adaptive_item_metadata_v262') is null
    or to_regclass('public.multigrade_diagnostic_blueprints_v263') is null
    or to_regclass('public.multigrade_learning_route_contract_v264') is null
    or to_regclass('public.multigrade_assessment_certification_v264') is null
    or to_regclass('public.multigrade_assessment_readiness_v264') is null then
   raise exception 'Falta arquitectura V26.1-V26.4';
 end if;

 select count(*) into v_calib_col from information_schema.columns
 where table_schema='public' and table_name='multigrade_adaptive_item_metadata_v262' and column_name='calibration_status';
 select count(*) into v_origin_col from information_schema.columns
 where table_schema='public' and table_name='multigrade_adaptive_item_metadata_v262' and column_name='metadata_origin';
 if v_calib_col<>1 or v_origin_col<>1 then
   raise exception 'Se requiere RC2: faltan calibration_status/metadata_origin';
 end if;

 select count(*) into v_existing from public.deep_learning_paths_v250
 where course_id='cl-8-basico' and content_version='v27.5';
 if v_existing>0 then raise exception 'V27.5-V27.9 8B ya parece instalada (% topics); no repitas SQL 135',v_existing; end if;

 select count(*) into v3items from public.multigrade_assessment_items_v261 where course_id='cl-3-medio';
 select count(*) into v3meta from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-3-medio';
 select count(*) into v3auto from public.multigrade_assessment_readiness_v264
 where course_id='cl-3-medio' and auto_gate_pass;
 select count(*) into v3deep from public.deep_learning_paths_v250
 where course_id='cl-3-medio' and content_version='v26.0' and status='staging';
 select count(*) into v3pub from public.deep_learning_paths_v250 where course_id='cl-3-medio' and status='published';
 if v3items<>624 or v3meta<>624 or v3auto<>24 or v3deep<>24 or v3pub<>0 then
   raise exception 'Baseline 3M V26 alterado: items %, meta %, auto %, deep %, pub %',v3items,v3meta,v3auto,v3deep,v3pub;
 end if;

 select count(*) into v4stage from public.deep_learning_paths_v250 where course_id='cl-4-medio' and status='staging';
 select count(*) into v4pub from public.deep_learning_paths_v250 where course_id='cl-4-medio' and status='published';
 select count(*) into vqueue from public.deferred_review_queue_v258;
 if v4stage<>24 or v4pub<>0 or vqueue<>120 then
   raise exception 'Baseline V25/V25.8 alterado: 4M staging %, pub %, queue %',v4stage,v4pub,vqueue;
 end if;

 select count(*) into vp from public.school_practice_items where code like '4M-V225-P-%' and is_published;
 select count(*) into vd from public.school_diagnostic_items where diagnostic_version='4m-fg-v225' and is_published;
 select count(*) into vr from public.school_review_items where code like '4M-V225-R-%' and is_published;
 select count(*) into vs from public.school_review_sets where id like '4m-fg-v225-%' and is_published;
 select count(*) into vrel from public.content_releases_v240 where release_key='4m-v240' and status='applied';
 if vp<>480 or vd<>72 or vr<>72 or vs<>4 or vrel<>1 then
   raise exception 'V24 fuera de baseline: %,%,%,%,release %',vp,vd,vr,vs,vrel;
 end if;
end $$;

-- Dependency guard: V26.5–V26.9 2M must remain intact before expanding 8B.
do $$
declare
 d int; st int; pub int; nd int; strong int; ai int; am int; auto int; rel int;
 src boolean; live boolean;
begin
 select count(*) into d from public.deep_learning_paths_v250
 where course_id='cl-2-medio' and content_version='v26.5';
 select count(*) into st from public.deep_learning_paths_v250
 where course_id='cl-2-medio' and content_version='v26.5' and status='staging';
 select count(*) into pub from public.deep_learning_paths_v250
 where course_id='cl-2-medio' and status='published';
 select count(*) into nd from public.curriculum_nodes_v254
 where course_id='cl-2-medio' and is_active;
 select count(*) into strong from public.curriculum_coverage_v254 c
 join public.deep_learning_paths_v250 p on p.topic_id=c.topic_id
 where p.course_id='cl-2-medio' and p.content_version='v26.5' and c.auto_state='strong';
 select count(*) into ai from public.multigrade_assessment_items_v261
 where course_id='cl-2-medio';
 select count(*) into am from public.multigrade_adaptive_item_metadata_v262
 where course_id='cl-2-medio';
 select count(*) into auto from public.multigrade_assessment_readiness_v264
 where course_id='cl-2-medio' and auto_gate_pass;
 select count(*) into rel from public.multigrade_assessment_readiness_v264
 where course_id='cl-2-medio' and release_candidate;
 select requires_revalidation_before_release into src
 from public.multigrade_curriculum_source_snapshot_v269 where course_id='cl-2-medio';
 select live_student_delivery into live
 from public.multigrade_course_runtime_gate_v269 where course_id='cl-2-medio';

 if d<>24 or st<>24 or pub<>0 or nd<>96 or strong<>96
    or ai<>624 or am<>624 or auto<>24 or rel<>0
    or not coalesce(src,false) or coalesce(live,true) then
   raise exception 'Baseline 2M V26.5-V26.9 alterado: deep %, staging %, pub %, nodes %, strong %, items %, meta %, auto %, release %, revalidate %, live %',
    d,st,pub,nd,strong,ai,am,auto,rel,src,live;
 end if;

 if exists(select 1 from public.multigrade_assessment_items_v261 where course_id='cl-8-basico')
    or exists(select 1 from public.multigrade_curriculum_source_snapshot_v269 where course_id='cl-8-basico')
    or exists(select 1 from public.curriculum_nodes_v254 where course_id='cl-8-basico') then
   raise exception 'V27.5-V27.9 8B tiene artefactos previos; no ejecutes SQL 135 sobre un estado parcial o una arquitectura curricular 8B previa';
 end if;
end $$;

-- Dependency guard: V27.0–V27.4 1M must remain intact before expanding 8B.
do $$
declare
 d int; st int; pub int; nd int; strong int; ai int; am int; auto int; rel int;
 src boolean; live boolean;
begin
 select count(*) into d from public.deep_learning_paths_v250 where course_id='cl-1-medio' and content_version='v27.0';
 select count(*) into st from public.deep_learning_paths_v250 where course_id='cl-1-medio' and content_version='v27.0' and status='staging';
 select count(*) into pub from public.deep_learning_paths_v250 where course_id='cl-1-medio' and status='published';
 select count(*) into nd from public.curriculum_nodes_v254 where course_id='cl-1-medio' and is_active;
 select count(*) into strong from public.curriculum_coverage_v254 c
 join public.deep_learning_paths_v250 p on p.topic_id=c.topic_id
 where p.course_id='cl-1-medio' and p.content_version='v27.0' and c.auto_state='strong';
 select count(*) into ai from public.multigrade_assessment_items_v261 where course_id='cl-1-medio';
 select count(*) into am from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-1-medio';
 select count(*) into auto from public.multigrade_assessment_readiness_v264 where course_id='cl-1-medio' and auto_gate_pass;
 select count(*) into rel from public.multigrade_assessment_readiness_v264 where course_id='cl-1-medio' and release_candidate;
 select requires_revalidation_before_release into src from public.multigrade_curriculum_source_snapshot_v269 where course_id='cl-1-medio';
 select live_student_delivery into live from public.multigrade_course_runtime_gate_v269 where course_id='cl-1-medio';

 if d<>30 or st<>30 or pub<>0 or nd<>120 or strong<>120 or ai<>780 or am<>780 or auto<>30 or rel<>0
    or not coalesce(src,false) or coalesce(live,true) then
   raise exception 'Baseline 1M V27.0-V27.4 alterado: deep %, staging %, pub %, nodes %, strong %, items %, meta %, auto %, release %, revalidate %, live %',
    d,st,pub,nd,strong,ai,am,auto,rel,src,live;
 end if;
end $$;

-- V27.5 · curriculum/source snapshot --------------------------------
create table if not exists public.multigrade_curriculum_source_snapshot_v269(
 course_id text primary key references public.mathlabs_course_catalog_v259(course_id),
 snapshot_date date not null,
 curriculum_basis text not null,
 course_url text not null,
 program_url text not null,
 update_process_url text,
 update_process_status text not null default 'monitoring',
 requires_revalidation_before_release boolean not null default true,
 revalidated_at timestamptz,
 revalidated_by uuid references auth.users(id) on delete set null,
 revalidation_notes text,
 updated_at timestamptz not null default now()
);

create table if not exists public.multigrade_course_runtime_gate_v269(
 course_id text primary key references public.mathlabs_course_catalog_v259(course_id),
 content_version text not null,
 assessment_version text not null,
 adaptive_calibration_status text not null default 'heuristic_candidate',
 human_content_review_required boolean not null default true,
 human_assessment_review_required boolean not null default true,
 live_student_delivery boolean not null default false,
 release_candidate boolean not null default false,
 blocker_codes jsonb not null default '[]'::jsonb,
 updated_at timestamptz not null default now(),
 check(live_student_delivery=false),
 check(release_candidate=false)
);

alter table public.multigrade_curriculum_source_snapshot_v269 enable row level security;
alter table public.multigrade_course_runtime_gate_v269 enable row level security;
revoke all on public.multigrade_curriculum_source_snapshot_v269,public.multigrade_course_runtime_gate_v269
from public,anon,authenticated;

