from jsonb_to_recordset($sources$[{"source_key":"mineduc-8b-course","course_id":"cl-8-basico","kind":"official_curriculum_page","title":"Matemática 8.º básico","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico","authority":"UCE Mineduc","notes":"Currículo oficial actualmente publicado."},{"source_key":"mineduc-8b-program","course_id":"cl-8-basico","kind":"official_program","title":"Programa de Estudio Matemática 8.º básico","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-8-basico","authority":"UCE Mineduc","notes":"Programa oficial; ficha 2024."},{"source_key":"mineduc-8b-update-1b-2m","course_id":"cl-8-basico","kind":"official_update_process","title":"Actualización Curricular 1.º básico a 2.º medio","url":"https://www.curriculumnacional.cl/actualizacion-curricular","authority":"Mineduc","notes":"Proceso en seguimiento; requiere revalidación antes de release."},{"source_key":"mineduc-8b-oa-01","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 01","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-01","authority":"UCE Mineduc","notes":"Multiplicación y división de números enteros, con representaciones, regla de signos y resolución de problemas."},{"source_key":"mineduc-8b-oa-02","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 02","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-02","authority":"UCE Mineduc","notes":"Multiplicación y división de números racionales en problemas, conectando fracciones, decimales y recta numérica."},{"source_key":"mineduc-8b-oa-03","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 03","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-03","authority":"UCE Mineduc","notes":"Multiplicación, división y potencias de potencias con base racional y exponente entero."},{"source_key":"mineduc-8b-oa-04","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 04","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-04","authority":"UCE Mineduc","notes":"Raíces cuadradas de números naturales mediante estimación, representaciones y aplicaciones."},{"source_key":"mineduc-8b-oa-05","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 05","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-05","authority":"UCE Mineduc","notes":"Variaciones porcentuales en contextos diversos, con representaciones y registro del procedimiento."},{"source_key":"mineduc-8b-oa-06","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 06","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-06","authority":"UCE Mineduc","notes":"Operaciones con expresiones algebraicas, representaciones pictóricas/simbólicas y formas factorizadas."},{"source_key":"mineduc-8b-oa-07","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 07","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-07","authority":"UCE Mineduc","notes":"Noción de función mediante cambio lineal, tablas, máquinas, reglas y representaciones."},{"source_key":"mineduc-8b-oa-08","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 08","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-08","authority":"UCE Mineduc","notes":"Modelación de situaciones mediante ecuaciones lineales con coeficientes racionales."},{"source_key":"mineduc-8b-oa-09","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 09","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-09","authority":"UCE Mineduc","notes":"Resolución de inecuaciones lineales con coeficientes racionales mediante representaciones gráficas y simbólicas."},{"source_key":"mineduc-8b-oa-10","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 10","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-10","authority":"UCE Mineduc","notes":"Función afín como traslación de una función lineal, representaciones y aplicaciones."},{"source_key":"mineduc-8b-oa-11","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 11","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-11","authority":"UCE Mineduc","notes":"Área de superficie y volumen de prismas rectos y cilindros, incluyendo redes y estimación."},{"source_key":"mineduc-8b-oa-12","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 12","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-12","authority":"UCE Mineduc","notes":"Validez y aplicación del teorema de Pitágoras en representaciones y problemas."},{"source_key":"mineduc-8b-oa-13","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 13","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-13","authority":"UCE Mineduc","notes":"Posición y movimiento de figuras 2D mediante traslaciones, rotaciones, reflexiones y vectores."},{"source_key":"mineduc-8b-oa-14","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 14","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-14","authority":"UCE Mineduc","notes":"Composición de rotaciones, traslaciones y reflexiones en plano cartesiano y espacio."},{"source_key":"mineduc-8b-oa-15","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 15","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-15","authority":"UCE Mineduc","notes":"Medidas de posición, percentiles y cuartiles, diagramas de cajón y comparación de poblaciones."},{"source_key":"mineduc-8b-oa-16","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 16","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-16","authority":"UCE Mineduc","notes":"Evaluación crítica de presentaciones de datos y gráficos, incluyendo posibles manipulaciones."},{"source_key":"mineduc-8b-oa-17","course_id":"cl-8-basico","kind":"official_oa","title":"MA08 OA 17","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/8-basico/ma08-oa-17","authority":"UCE Mineduc","notes":"Principio combinatorio multiplicativo mediante situaciones, tablas, árboles y cálculo de probabilidades."},{"source_key":"mineduc-8b-u1","course_id":"cl-8-basico","kind":"official_program_unit","title":"U1: Raíces cuadradas. Multiplicación y división de números enteros y de potencias.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-8-basico","authority":"UCE Mineduc","notes":"Unidad del programa oficial."},{"source_key":"mineduc-8b-u2","course_id":"cl-8-basico","kind":"official_program_unit","title":"U2: Expresiones algebraicas. Noción de función. Cambio lineal y afín. Ecuaciones e inecuaciones lineales.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-8-basico","authority":"UCE Mineduc","notes":"Unidad del programa oficial."},{"source_key":"mineduc-8b-u3","course_id":"cl-8-basico","kind":"official_program_unit","title":"U3: Teorema de Pitágoras. Prismas y cilindros. Posición y movimientos.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-8-basico","authority":"UCE Mineduc","notes":"Unidad del programa oficial."},{"source_key":"mineduc-8b-u4","course_id":"cl-8-basico","kind":"official_program_unit","title":"U4: Medidas de posición y el principio combinatorio multiplicativo de probabilidades.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-8-basico","authority":"UCE Mineduc","notes":"Unidad del programa oficial."}]$sources$::jsonb)
