insert into public.knowledge_topics(
 id,course_id,axis_id,slug,title,summary,difficulty,estimated_minutes,sort_order,content_status,is_published
)
select x.id,x.course_id,a.id,x.slug,x.title,x.summary,x.difficulty,x.estimated_minutes,x.sort_order,'review',false
from jsonb_to_recordset($knowledge$[{"id":"topic-v275-ma08-oa01a","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa01a","title":"Multiplicación de números enteros","summary":"El signo del producto depende de la paridad de factores negativos.","difficulty":"Fundamental","estimated_minutes":45,"sort_order":1,"content_status":"review","is_published":false,"oa_code":"MA08 OA 01"},{"id":"topic-v275-ma08-oa01b","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa01b","title":"División de enteros y problemas","summary":"Dividir enteros combina cociente absoluto y regla de signos.","difficulty":"Intermedio","estimated_minutes":45,"sort_order":2,"content_status":"review","is_published":false,"oa_code":"MA08 OA 01"},{"id":"topic-v275-ma08-oa02a","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa02a","title":"Producto de números racionales","summary":"Multiplicar racionales conserva equivalencia entre fracciones y decimales.","difficulty":"Avanzado","estimated_minutes":45,"sort_order":3,"content_status":"review","is_published":false,"oa_code":"MA08 OA 02"},{"id":"topic-v275-ma08-oa02b","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa02b","title":"División de racionales y recta numérica","summary":"Dividir por un racional no nulo equivale a multiplicar por su recíproco.","difficulty":"Fundamental","estimated_minutes":45,"sort_order":4,"content_status":"review","is_published":false,"oa_code":"MA08 OA 02"},{"id":"topic-v275-ma08-oa03a","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa03a","title":"Leyes de potencias con exponente entero","summary":"Las leyes de exponentes preservan el valor al combinar potencias de igual base.","difficulty":"Intermedio","estimated_minutes":45,"sort_order":5,"content_status":"review","is_published":false,"oa_code":"MA08 OA 03"},{"id":"topic-v275-ma08-oa03b","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa03b","title":"Potencia de potencia y exponentes negativos","summary":"Exponentes negativos representan recíprocos y la potencia de potencia multiplica exponentes.","difficulty":"Avanzado","estimated_minutes":45,"sort_order":6,"content_status":"review","is_published":false,"oa_code":"MA08 OA 03"},{"id":"topic-v275-ma08-oa04a","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa04a","title":"Raíz cuadrada y cuadrados perfectos","summary":"La raíz cuadrada principal revierte elevar al cuadrado en cantidades no negativas.","difficulty":"Fundamental","estimated_minutes":45,"sort_order":7,"content_status":"review","is_published":false,"oa_code":"MA08 OA 04"},{"id":"topic-v275-ma08-oa04b","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa04b","title":"Estimación y aplicaciones de raíces","summary":"Las raíces no exactas se ubican entre cuadrados perfectos consecutivos.","difficulty":"Intermedio","estimated_minutes":45,"sort_order":8,"content_status":"review","is_published":false,"oa_code":"MA08 OA 04"},{"id":"topic-v275-ma08-oa05a","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa05a","title":"Aumentos y disminuciones porcentuales","summary":"Una variación porcentual modifica una cantidad mediante un factor multiplicativo.","difficulty":"Avanzado","estimated_minutes":45,"sort_order":9,"content_status":"review","is_published":false,"oa_code":"MA08 OA 05"},{"id":"topic-v275-ma08-oa05b","course_id":"cl-8-basico","axis_slug":"v275-8b-u1","slug":"v275-oa05b","title":"Variaciones sucesivas y problemas","summary":"Variaciones sucesivas se componen multiplicando factores, no sumando porcentajes.","difficulty":"Fundamental","estimated_minutes":45,"sort_order":10,"content_status":"review","is_published":false,"oa_code":"MA08 OA 05"},{"id":"topic-v275-ma08-oa06a","course_id":"cl-8-basico","axis_slug":"v275-8b-u2","slug":"v275-oa06a","title":"Suma, producto y área algebraica","summary":"Las operaciones algebraicas siguen distributividad y combinación de términos semejantes.","diffic