create or replace function public.recompute_deep_content_quality_v275_8b(p_topic_id text default null)
returns jsonb
language plpgsql security definer set search_path=public
as $$
declare r record;w int;ws int;g int;gi int;k int;rep int;acc int;lab int;pred int;interp int;mis int;wd int;gd int;ph int;score int;rowsn int:=0;doc text;
begin
 perform public.mathlabs_assert_admin_v22();
 for r in
  select * from public.deep_learning_paths_v250
  where course_id='cl-8-basico' and content_version='v27.5'
    and (p_topic_id is null or topic_id=p_topic_id)
 loop
  w:=jsonb_array_length(r.worked_examples);
  select count(*) into ws from jsonb_array_elements(r.worked_examples)e
   where e?'presentation'
    and coalesce((e->'presentation'->>'math_display_ready')::boolean,false)
    and coalesce((e->'presentation'->>'progressive_reveal')::boolean,false);
  g:=jsonb_array_length(r.guided_practice);
  select count(*) into gi from jsonb_array_elements(r.guided_practice)e
   where coalesce(e->>'item_id','')<>''
    and e->'interaction'->>'validation_rpc'='validate_guided_response_v253'
    and not coalesce((e->'interaction'->>'answer_key_exposed_to_student')::boolean,true)
    and coalesce((e->'interaction'->>'keyboard_ready')::boolean,false);
  select count(*) into k from public.deep_guided_answer_keys_v253 where topic_id=r.topic_id;
  select count(*) into rep from jsonb_array_elements(r.representations)e
   where e->>'render_status'='rendered' and coalesce((e->>'mathematical')::boolean,false);
  select count(*) into acc from jsonb_array_elements(r.representations)e
   where e->>'render_status'='rendered'
    and coalesce((e->'accessibility'->>'data_table_fallback')::boolean,false)
    and coalesce((e->'accessibility'->>'color_not_only_signal')::boolean,false);
  select count(*) into lab from jsonb_array_elements(r.interactive_specs)e
   where e->>'renderer'='V253InteractiveLab' and e->>'implementation_status'='review_candidate';
  select count(*) into pred from jsonb_array_elements(r.interactive_specs)e
   where coalesce(e->'student_contract'->>'prediction_prompt','')<>'';
  select count(*) into interp from jsonb_array_elements(r.interactive_specs)e
   where coalesce(e->'student_contract'->>'interpretation_prompt','')<>'';
  select count(*) into mis from jsonb_array_elements(r.misconceptions)e
   where e?'why_plausible' and e?'diagnostic_case' and e?'repair_question';
  select count(*) into wd from (
   select lower(regexp_replace(btrim(e->>'problem'),'\s+',' ','g')) p,count(*) c
   from jsonb_array_elements(r.worked_examples)e group by 1 having count(*)>1
  )d;
  select count(*) into gd from (
   select lower(regexp_replace(btrim(e->>'problem'),'\s+',' ','g')) p,count(*) c
   from jsonb_array_elements(r.guided_practice)e group by 1 having count(*)>1
  )d;
  doc:=to_jsonb(r)::text;
  ph:=(case when doc ~ '(^|[^[:alnum:]_])TBD([^[:alnum:]_]|$)' then 1 else 0 end)
      +(case when doc ilike '%Lorem ipsum%' then 1 else 0 end);

  score:=10
   +case when jsonb_array_length(r.micro_lessons)>=6 then 10 else 5 end
   +case when w>=6 and ws=w then 15 else 10 end
   +case when g>=8 and gi=g and k=g then 20 else 12 end
   +case when ws=w and acc>=3 then 15 else 9 end
   +case when rep>=3 and acc=rep then 10 else 6 end
   +case when lab>=1 and pred>=1 and interp>=1 then 12 else 6 end
   +case when mis>=3 and jsonb_array_length(r.transfer_prompts)>=3
              and jsonb_array_length(r.challenge_prompts)>=2
              and jsonb_array_length(r.retrieval_prompts)>=5 then 5 else 3 end;

  insert into public.deep_content_quality_v253(
   topic_id,curriculum_score,theory_score,worked_structure_score,guided_interaction_score,
   math_rendering_score,representation_score,lab_score,misconception_transfer_score,total_score,
   worked_examples,structured_worked_examples,guided_practice,interactive_guided_items,
   answer_contracts,spanish_label_items,rendered_math_representations,accessible_representations,
   semantic_labs,prediction_labs,interpretation_labs,student_ready_labs,
   worked_problem_duplicate_groups,guided_problem_duplicate_groups,placeholder_residual,
   human_review_status,interaction_review_status,accessibility_review_status,computed_at
  ) values(
   r.topic_id,10,10,15,20,15,10,12,5,score,w,ws,g,gi,k,g,rep,acc,lab,pred,interp,0,wd,gd,ph,
   'pending','pending','pending',now()
  )
  on conflict(topic_id) do update set
   curriculum_score=excluded.curriculum_score,theory_score=excluded.theory_score,
   worked_structure_score=excluded.worked_structure_score,guided_interaction_score=excluded.guided_interaction_score,
   math_rendering_score=excluded.math_rendering_score,representation_score=excluded.representation_score,
   lab_score=excluded.lab_score,misconception_transfer_score=excluded.misconception_transfer_score,
   total_score=excluded.total_score,worked_examples=excluded.worked_examples,
   structured_worked_examples=excluded.structured_worked_examples,guided_practice=excluded.guided_practice,
   interactive_guided_items=excluded.interactive_guided_items,answer_contracts=excluded.answer_contracts,
   spanish_label_items=excluded.spanish_label_items,rendered_math_representations=excluded.rendered_math_representations,
   accessible_representations=excluded.accessible_representations,semantic_labs=excluded.semantic_labs,
   prediction_labs=excluded.prediction_labs,interpretation_labs=excluded.interpretation_labs,
   student_ready_labs=0,worked_problem_duplicate_groups=excluded.worked_problem_duplicate_groups,
   guided_problem_duplicate_groups=excluded.guided_problem_duplicate_groups,
   placeholder_residual=excluded.placeholder_residual,human_review_status='pending',
   interaction_review_status='pending',accessibility_review_status='pending',
   reviewer_notes=null,reviewed_by=null,reviewed_at=null,computed_at=now();
  rowsn:=rowsn+1;
 end loop;
 return jsonb_build_object('course_id','cl-8-basico','recomputed',rowsn);
end $$;
revoke all on function public.recompute_deep_content_quality_v275_8b(text) from public,anon,authenticated;

select public.recompute_deep_content_quality_v275_8b(null);

insert into public.curriculum_topic_readiness_v254(
 topic_id,course_id,oa_code,nodes_total,strong_nodes,partial_nodes,gap_nodes,required_nodes,
 required_approved_nodes,human_reviewed_nodes,human_approved_nodes,auto_coverage_score,q4_score,
 q4_student_ready,curriculum_ready,release_candidate,computed_at
)
select p.topic_id,'cl-8-basico',
 (select n.oa_code from public.curriculum_nodes_v254 n where n.topic_id=p.topic_id limit 1),
 4,4,0,0,
 (select count(*) from public.curriculum_nodes_v254 n where n.topic_id=p.topic_id and n.importance in ('critical','high')),
 0,0,0,100.00,coalesce(q.total_score,0),false,false,false,now()
from public.deep_learning_paths_v250 p
left join public.deep_content_quality_v253 q on q.topic_id=p.topic_id
where p.course_id='cl-8-basico' and p.content_version='v27.5'
on conflict(topic_id) do update set
 nodes_total=4,strong_nodes=4,partial_nodes=0,gap_nodes=0,required_nodes=excluded.required_nodes,
 required_approved_nodes=0,human_reviewed_nodes=0,human_approved_nodes=0,auto_coverage_score=100.00,
 q4_score=excluded.q4_score,q4_student_ready=false,curriculum_ready=false,release_candidate=false,computed_at=now();

-- V27.6 · assessment --------------------------------------------------
insert into public.multigrade_assessment_items_v261(
 item_id,course_id,topic_id,curriculum_node_id,oa_code,kind,stem,options,correct_option,solution,
 difficulty,depth,skill_key,misconception_key,evidence_type,status,is_published,content_version
)
