insert into public.multigrade_assessment_certification_v264(
 topic_id,course_id,priority,content_fingerprint
)
select p.topic_id,'cl-8-basico',
 case when right(p.topic_id,1)='a' then 'A' else 'B' end,
 md5(string_agg(
  i.item_id||'|'||i.stem||'|'||i.options::text||'|'||i.correct_option||'|'||i.solution,
  '§' order by i.item_id
 ))
from public.deep_learning_paths_v250 p
join public.multigrade_assessment_items_v261 i on i.topic_id=p.topic_id
where p.course_id='cl-8-basico' and p.content_version='v27.5'
group by p.topic_id;

create or replace function public.refresh_v269_course_assessment_readiness(p_course_id text)
returns jsonb
language plpgsql security definer set search_path=public
as $$
declare r record;pr int;di int;rv int;meta int;heur int;cal int;nodes int;strong int;q4 int;uniq int;
 fp text;cert record;auto_ok boolean;blocks jsonb;rowsn int:=0;src_revalidate boolean:=false;
begin
 perform public.mathlabs_assert_admin_v22();

 select coalesce(requires_revalidation_before_release,false) into src_revalidate
 from public.multigrade_curriculum_source_snapshot_v269 where course_id=p_course_id;

 for r in
  select distinct p.topic_id
  from public.deep_learning_paths_v250 p
  join public.multigrade_assessment_items_v261 i on i.topic_id=p.topic_id
  where p.course_id=p_course_id
  order by p.topic_id
 loop
   select
    count(*) filter(where kind='practice'),
    count(*) filter(where kind='diagnostic'),
    count(*) filter(where kind='review'),
    count(*) filter(where jsonb_array_length(options)=4 and
      (select count(distinct lower(regexp_replace(o->>'text','\s+','','g')))
       from jsonb_array_elements(options)o)=4)
   into pr,di,rv,uniq
   from public.multigrade_assessment_items_v261 where topic_id=r.topic_id;

   select count(*),
          count(*) filter(where calibration_status='heuristic_candidate'),
          count(*) filter(where calibration_status='calibrated')
   into meta,heur,cal
   from public.multigrade_adaptive_item_metadata_v262
   where topic_id=r.topic_id and eligible_for_adaptive_session;

   select count(*) into nodes from public.curriculum_nodes_v254 where topic_id=r.topic_id and is_active;
   select count(*) into strong from public.curriculum_coverage_v254 where topic_id=r.topic_id and auto_state='strong';
   select coalesce(total_score,0) into q4 from public.deep_content_quality_v253 where topic_id=r.topic_id;

   select md5(string_agg(
    i.item_id||'|'||i.stem||'|'||i.options::text||'|'||i.correct_option||'|'||i.solution,
    '§' order by i.item_id
   )) into fp
   from public.multigrade_assessment_items_v261 i where i.topic_id=r.topic_id;

   select * into cert from public.multigrade_assessment_certification_v264 where topic_id=r.topic_id;
   if cert.content_fingerprint<>fp and (
      cert.certified or cert.mathematical_status<>'pending' or cert.curriculum_status<>'pending'
      or cert.editorial_status<>'pending' or cert.distractor_status<>'pending'
      or cert.adaptive_status<>'pending'
   ) then
     insert into public.multigrade_assessment_certification_invalidation_v264(
      topic_id,previous_fingerprint,current_fingerprint,previous_certified
     ) values(r.topic_id,cert.content_fingerprint,fp,cert.certified);
     update public.multigrade_assessment_certification_v264 set
      mathematical_status='pending',curriculum_status='pending',editorial_status='pending',
      distractor_status='pending',adaptive_status='pending',reviewer_notes=null,certified=false,
      reviewed_by=null,reviewed_at=null,content_fingerprint=fp,updated_at=now()
     where topic_id=r.topic_id;
   elsif cert.content_fingerprint<>fp then
     update public.multigrade_assessment_certification_v264
     set content_fingerprint=fp,updated_at=now() where topic_id=r.topic_id;
   end if;

   select * into cert from public.multigrade_assessment_certification_v264 where topic_id=r.topic_id;

   auto_ok:=(
    pr=20 and di=3 and rv=3 and meta=26 and heur+cal=26
    and nodes=4 and strong=4 and q4>=97 and uniq=26
    and not exists(
      select 1 from public.multigrade_assessment_items_v261 i
      where i.topic_id=r.topic_id and (i.status<>'staging' or i.is_published)
    )
   );

   blocks:='[]'::jsonb;
   if not auto_ok then blocks:=blocks||'"AUTO_GATE_NOT_READY"'::jsonb; end if;
   if not cert.certified then blocks:=blocks||'"HUMAN_ASSESSMENT_CERTIFICATION_PENDING"'::jsonb; end if;
   if cal<26 then blocks:=blocks||'"ADAPTIVE_CALIBRATION_PENDING"'::jsonb; end if;
   if src_revalidate then blocks:=blocks||'"CURRICULUM_REVALIDATION_REQUIRED_BEFORE_RELEASE"'::jsonb; end if;
   blocks:=blocks||'"LIVE_STUDENT_DELIVERY_DISABLED"'::jsonb;

   insert into public.multigrade_assessment_readiness_v264(
    topic_id,course_id,practice_items,diagnostic_items,review_items,adaptive_metadata_rows,
    curriculum_nodes,strong_nodes,q4_score,unique_option_items,auto_gate_pass,human_certified,
    release_candidate,blocker_codes,refreshed_at
   ) values(
    r.topic_id,p_course_id,pr,di,rv,meta,nodes,strong,q4,uniq,auto_ok,cert.certified,false,blocks,now()
   )
   on conflict(topic_id) do update set
    course_id=excluded.course_id,practice_items=excluded.practice_items,
    diagnostic_items=excluded.diagnostic_items,review_items=excluded.review_items,
    adaptive_metadata_rows=excluded.adaptive_metadata_rows,curriculum_nodes=excluded.curriculum_nodes,
    strong_nodes=excluded.strong_nodes,q4_score=excluded.q4_score,
    unique_option_items=excluded.unique_option_items,auto_gate_pass=excluded.auto_gate_pass,
    human_certified=excluded.human_certified,release_candidate=false,
    blocker_codes=excluded.blocker_codes,refreshed_at=now();
   rowsn:=rowsn+1;
 end loop;

 return jsonb_build_object('course_id',p_course_id,'refreshed_topics',rowsn);
end $$;
revoke all on function public.refresh_v269_course_assessment_readiness(text) from public,anon,authenticated;

select public.refresh_v269_course_assessment_readiness('cl-8-basico');

create or replace function public.preview_v267_adaptive_items(
 p_course_id text,p_topic_id text,p_target_difficulty int default 3,p_limit int default 5
)
returns table(item_id text,stem text,difficulty int,depth int,skill_key text,misconception_key text,calibration_status text)
language plpgsql security definer set search_path=public
as $$
declare u uuid:=auth.uid();adm boolean:=false;
begin
 if u is null then raise exception 'authentication required'; end if;
 select public.is_learning_admin() into adm;
 if not coalesce(adm,false) then raise exception 'admin required'; end if;
 if p_limit<1 or p_limit>20 then raise exception 'p_limit debe estar entre 1 y 20'; end if;
 return query
 select i.item_id,i.stem,m.difficulty,m.depth,m.skill_key,m.misconception_key,m.calibration_status
 from public.multigrade_assessment_items_v261 i
 join public.multigrade_adaptive_item_metadata_v262 m using(item_id)
 where i.course_id=p_course_id and i.topic_id=p_topic_id
  and i.kind='practice' and i.status='staging' and not i.is_published
 order by abs(m.difficulty-p_target_difficulty),m.depth desc,i.item_id
 limit p_limit;
end $$;
revoke all on function public.preview_v267_adaptive_items(text,text,int,int) from public,anon,authenticated;
grant execute on function public.preview_v267_adaptive_items(text,text,int,int) to authenticated;

create or replace function public.preview_v268_diagnostic(p_course_id text,p_limit int default 30)
returns table(item_id text,topic_id text,oa_code text,stem text,difficulty int,depth int)
language plpgsql security definer set search_path=public
as $$
declare
 u uuid:=auth.uid(); adm boolean:=false;
 min_allowed int:=24; max_allowed int:=30;
begin
 if u is null then raise exception 'authentication required'; end if;
 select public.is_learning_admin() into adm;
 if not coalesce(adm,false) then raise exception 'admin required'; end if;

 if p_course_id='cl-8-basico' then
   min_allowed:=34; max_allowed:=40;
 elsif p_course_id='cl-1-medio' then
   min_allowed:=30; max_allowed:=36;
 end if;

 if p_limit<min_allowed or p_limit>max_allowed then
   raise exception 'p_limit fuera del rango permitido para %: % a %',p_course_id,min_allowed,max_allowed;
 end if;

 return query
 with ranked as(
  select i.*,
   row_number() over(partition by i.topic_id order by i.difficulty,i.item_id) rn
  from public.multigrade_assessment_items_v261 i
  where i.course_id=p_course_id and i.kind='diagnostic'
    and i.status='staging' and not i.is_published
 )
 select r.item_id,r.topic_id,r.oa_code,r.stem,r.difficulty,r.depth
 from ranked r
 order by r.rn,r.topic_id
 limit p_limit;
end $$;
revoke all on function public.preview_v268_diagnostic(text,int) from public,anon,authenticated;
grant execute on function public.preview_v268_diagnostic(text,int) to authenticated;

create or replace function public.review_v269_assessment_topic(
 p_topic_id text,p_mathematical text,p_curriculum text,p_editorial text,
 p_distractor text,p_adaptive text,p_notes text
)
returns jsonb
language plpgsql security definer set search_path=public
as $$
declare u uuid:=auth.uid();adm boolean:=false;ok boolean;res jsonb;cid text;
begin
 if u is null then raise exception 'authentication required'; end if;
 select public.is_learning_admin() into adm;
 if not coalesce(adm,false) then raise exception 'admin required'; end if;
 if p_mathematical not in ('pending','approved','needs_work')
  or p_curriculum not in ('pending','approved','needs_work')
  or p_editorial not in ('pending','approved','needs_work')
  or p_distractor not in ('pending','approved','needs_work')
  or p_adaptive not in ('pending','approved','needs_work') then
   raise exception 'Estado de revisión inválido';
 end if;
 if (p_mathematical<>'pending' or p_curriculum<>'pending' or p_editorial<>'pending'
     or p_distractor<>'pending' or p_adaptive<>'pending')
    and length(btrim(coalesce(p_notes,'')))<40 then
   raise exception 'La evidencia/nota debe tener al menos 40 caracteres';
 end if;

 select course_id into cid from public.multigrade_assessment_certification_v264 where topic_id=p_topic_id;
 if cid is null then raise exception 'Topic no encontrado'; end if;
 perform public.refresh_v269_course_assessment_readiness(cid);
 select auto_gate_pass into ok from public.multigrade_assessment_readiness_v264 where topic_id=p_topic_id;

 update public.multigrade_assessment_certification_v264 set
  mathematical_status=p_mathematical,curriculum_status=p_curriculum,editorial_status=p_editorial,
  distractor_status=p_distractor,adaptive_status=p_adaptive,reviewer_notes=btrim(p_notes),
  certified=coalesce(ok,false)
   and p_mathematical='approved' and p_curriculum='approved' and p_editorial='approved'
   and p_distractor='approved' and p_adaptive='approved',
  reviewed_by=u,reviewed_at=now(),updated_at=now()
 where topic_id=p_topic_id
 returning to_jsonb(multigrade_assessment_certification_v264.*) into res;

 perform public.refresh_v269_course_assessment_readiness(cid);
 return res;
end $$;
revoke all on function public.review_v269_assessment_topic(text,text,text,text,text,text,text) from public,anon,authenticated;
grant execute on function public.review_v269_assessment_topic(text,text,text,text,text,text,text) to authenticated;

create or replace function public.assert_v269_course_release_ready(p_course_id text)
returns jsonb
language plpgsql security definer set search_path=public
as $$
declare u uuid:=auth.uid();adm boolean:=false;src boolean;live boolean;rel boolean;pending int;uncal int;
begin
 if u is null then raise exception 'authentication required'; end if;
 select public.is_learning_admin() into adm;
 if not coalesce(adm,false) then raise exception 'admin required'; end if;

 select requires_revalidation_before_release into src
 from public.multigrade_curriculum_source_snapshot_v269 where course_id=p_course_id;
 select live_student_delivery,release_candidate into live,rel
 from public.multigrade_course_runtime_gate_v269 where course_id=p_course_id;

 select count(*) into pending
 from public.multigrade_assessment_certification_v264 where course_id=p_course_id and not certified;
 select count(*) into uncal
 from public.multigrade_adaptive_item_metadata_v262
 where course_id=p_course_id and calibration_status<>'calibrated';

 if coalesce(src,true) then raise exception 'Release blocked: curriculum source must be revalidated'; end if;
 if pending>0 then raise exception 'Release blocked: % assessment topics are not certified',pending; end if;
 if uncal>0 then raise exception 'Release blocked: % adaptive items are not calibrated',uncal; end if;
 if not coalesce(live,false) or not coalesce(rel,false) then
   raise exception 'Release blocked: runtime gate remains OFF';
 end if;
 return jsonb_build_object('release_ready',true,'course_id',p_course_id);
end $$;
revoke all on function public.assert_v269_course_release_ready(text) from public,anon,authenticated;
grant execute on function public.assert_v269_course_release_ready(text) to authenticated;

create or replace function public.get_v279_8b_expansion_overview()
returns jsonb
language plpgsql security definer set search_path=public
as $$
declare u uuid:=auth.uid();adm boolean:=false;res jsonb;
begin
 if u is null then raise exception 'authentication required'; end if;
 select public.is_learning_admin() into adm;
 if not coalesce(adm,false) then raise exception 'admin required'; end if;
 perform public.refresh_v269_course_assessment_readiness('cl-8-basico');

 select jsonb_build_object(
  'course_id','cl-8-basico',
  'curriculum_snapshot',(select to_jsonb(s) from public.multigrade_curriculum_source_snapshot_v269 s where s.course_id='cl-8-basico'),
  'official_oas',(select count(distinct n.oa_code) from public.curriculum_nodes_v254 n join public.deep_learning_paths_v250 p on p.topic_id=n.topic_id where p.course_id='cl-8-basico' and p.content_version='v27.5'),
  'deep_topics',(select count(*) from public.deep_learning_paths_v250 where course_id='cl-8-basico' and content_version='v27.5'),
  'curriculum_nodes',(select count(*) from public.curriculum_nodes_v254 where course_id='cl-8-basico' and is_active),
  'micro_lessons',(select sum(jsonb_array_length(micro_lessons)) from public.deep_learning_paths_v250 where course_id='cl-8-basico' and content_version='v27.5'),
  'worked_examples',(select sum(jsonb_array_length(worked_examples)) from public.deep_learning_paths_v250 where course_id='cl-8-basico' and content_version='v27.5'),
  'guided_practice',(select sum(jsonb_array_length(guided_practice)) from public.deep_learning_paths_v250 where course_id='cl-8-basico' and content_version='v27.5'),
  'practice',(select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-8-basico' and kind='practice'),
  'diagnostic',(select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-8-basico' and kind='diagnostic'),
  'review',(select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-8-basico' and kind='review'),
  'review_sets',(select count(*) from public.multigrade_review_sets_v261 where course_id='cl-8-basico'),
  'adaptive_metadata',(select count(*) from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-8-basico'),
  'heuristic_metadata',(select count(*) from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-8-basico' and calibration_status='heuristic_candidate'),
  'calibrated_metadata',(select count(*) from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-8-basico' and calibration_status='calibrated'),
  'diagnostic_blueprints',(select count(*) from public.multigrade_diagnostic_blueprints_v263 where course_id='cl-8-basico'),
  'route_contracts',(select count(*) from public.multigrade_learning_route_contract_v264 where course_id='cl-8-basico'),
  'auto_gate_topics',(select count(*) from public.multigrade_assessment_readiness_v264 where course_id='cl-8-basico' and auto_gate_pass),
  'human_certified_topics',(select count(*) from public.multigrade_assessment_certification_v264 where course_id='cl-8-basico' and certified),
  'release_candidates',(select count(*) from public.multigrade_assessment_readiness_v264 where course_id='cl-8-basico' and release_candidate),
  'published_deep_topics',(select count(*) from public.deep_learning_paths_v250 where course_id='cl-8-basico' and status='published'),
  'published_assessment_items',(select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-8-basico' and is_published),
  'live_student_delivery',(select live_student_delivery from public.multigrade_course_runtime_gate_v269 where course_id='cl-8-basico'),
  'topics',coalesce((
   select jsonb_agg(jsonb_build_object(
    'topic_id',r.topic_id,'practice',r.practice_items,'diagnostic',r.diagnostic_items,'review',r.review_items,
    'metadata',r.adaptive_metadata_rows,'q4',r.q4_score,'auto_gate',r.auto_gate_pass,
    'human_certified',r.human_certified,'release_candidate',r.release_candidate,'blockers',r.blocker_codes,
    'priority',c.priority
   ) order by c.priority,r.topic_id)
   from public.multigrade_assessment_readiness_v264 r
   join public.multigrade_assessment_certification_v264 c using(topic_id)
   where r.course_id='cl-8-basico'
  ),'[]'::jsonb)
 ) into res;
 return res;
end $$;
revoke all on function public.get_v279_8b_expansion_overview() from public,anon,authenticated;
grant execute on function public.get_v279_8b_expansion_overview() to authenticated;

-- Course inventory / status ------------------------------------------
update public.mathlabs_course_catalog_v259
set lifecycle_status='staging',content_version='v27.5',updated_at=now()
where course_id='cl-8-basico';

update public.mathlabs_course_import_contract_v259
set curriculum_import_status='validated',expected_oa_count=17,expected_topic_count=34,
 source_reference='Currículum Nacional · Matemática 8.º básico · snapshot 2026-08-11',
 next_action='8B staging completo V27.5-V27.9. Revalidar currículo oficial antes de release; luego expansión recomendada: 7B.',
 updated_at=now()
where course_id='cl-8-basico';

update public.mathlabs_course_module_readiness_v259
set readiness_status=case module_key
 when 'curriculum_map' then 'ready'
 when 'deep_learning' then 'staging'
 when 'worked_guided' then 'staging'
 when 'representations' then 'staging'
 when 'practice_bank' then 'staging'
 when 'diagnostic' then 'staging'
 when 'review' then 'staging'
 when 'adaptive_engine' then 'partial'
 when 'content_certification' then 'planned'
 when 'interaction_certification' then 'planned'
 when 'release_governance' then 'planned'
 else readiness_status end,
 details=details||jsonb_build_object(
  'v275_v279',true,'content_version','v27.5','assessment_version','v27.6',
  'curriculum_snapshot','2026-08-11','live_student_delivery',false,
  'curriculum_revalidation_before_release',true
 ),
 refreshed_at=now()
where course_id='cl-8-basico';

-- Keep V25.9 inventory generic for the V27 multi-grade expansion.
create or replace function public.refresh_v259_course_architecture()
returns jsonb
language plpgsql security definer set search_path=public
as $$
declare r record;tp int;nd int;ml int;we int;gp int;rr int;pi int;di int;ri int;mr int;mt int;score numeric;blocks jsonb;rowsn int:=0;
begin
 perform public.mathlabs_assert_admin_v22();
 for r in select * from public.mathlabs_course_catalog_v259 order by sequence_order loop
   select count(*),coalesce(sum(jsonb_array_length(micro_lessons)),0),
          coalesce(sum(jsonb_array_length(worked_examples)),0),
          coalesce(sum(jsonb_array_length(guided_practice)),0),
          coalesce(sum((select count(*) from jsonb_array_elements(representations)x where x->>'render_status'='rendered')),0)
   into tp,ml,we,gp,rr
   from public.deep_learning_paths_v250 where course_id=r.course_id and status<>'retired';

   select count(*) into nd from public.curriculum_nodes_v254 where course_id=r.course_id and is_active;
   pi:=0;di:=0;ri:=0;

   if exists(select 1 from public.multigrade_assessment_items_v261 where course_id=r.course_id) then
     select count(*) filter(where kind='practice'),count(*) filter(where kind='diagnostic'),count(*) filter(where kind='review')
     into pi,di,ri from public.multigrade_assessment_items_v261 where course_id=r.course_id;
   elsif r.course_id='cl-4-medio' then
     select count(*) into pi from public.school_practice_items where code like '4M-V225-P-%' and is_published;
     select count(*) into di from public.school_diagnostic_items where diagnostic_version='4m-fg-v225' and is_published;
     select count(*) into ri from public.school_review_items where code like '4M-V225-R-%' and is_published;
   end if;

   select count(*),count(*) filter(where readiness_status in ('ready','staging','production'))
   into mt,mr from public.mathlabs_course_module_readiness_v259 where course_id=r.course_id;

   score:=case when mt=0 then 0 else round(100.0*mr/mt,2) end;
   blocks:='[]'::jsonb;
   if tp=0 then blocks:=blocks||'"CONTENT_NOT_BUILT"'::jsonb; end if;
   if r.course_id in ('cl-8-basico','cl-1-medio','cl-2-medio') then
     blocks:=blocks||'"CURRICULUM_REVALIDATION_REQUIRED_BEFORE_RELEASE"'::jsonb;
     blocks:=blocks||'"HUMAN_CONTENT_REVIEW_PENDING"'::jsonb;
     blocks:=blocks||'"HUMAN_ASSESSMENT_CERTIFICATION_PENDING"'::jsonb;
     blocks:=blocks||'"ADAPTIVE_CALIBRATION_PENDING"'::jsonb;
     blocks:=blocks||'"LIVE_STUDENT_DELIVERY_DISABLED"'::jsonb;
   elsif r.course_id='cl-3-medio' then
     blocks:=blocks||'"ASSESSMENT_HUMAN_CERTIFICATION_PENDING"'::jsonb;
     blocks:=blocks||'"ADAPTIVE_CALIBRATION_PENDING"'::jsonb;
     blocks:=blocks||'"LIVE_STUDENT_DELIVERY_DISABLED"'::jsonb;
   elsif r.course_id='cl-4-medio' then
     blocks:=blocks||'"V25_HUMAN_CERTIFICATION_PENDING"'::jsonb;
   end if;

   insert into public.mathlabs_course_architecture_snapshot_v259(
    course_id,topics,curriculum_nodes,micro_lessons,worked_examples,guided_practice,rendered_representations,
    practice_items,diagnostic_items,review_items,modules_ready,modules_total,architecture_readiness,
    student_release_candidate,blocker_codes,refreshed_at
   ) values(r.course_id,tp,nd,ml,we,gp,rr,pi,di,ri,mr,mt,score,false,blocks,now())
   on conflict(course_id) do update set
    topics=excluded.topics,curriculum_nodes=excluded.curriculum_nodes,micro_lessons=excluded.micro_lessons,
    worked_examples=excluded.worked_examples,guided_practice=excluded.guided_practice,
    rendered_representations=excluded.rendered_representations,practice_items=excluded.practice_items,
    diagnostic_items=excluded.diagnostic_items,review_items=excluded.review_items,
    modules_ready=excluded.modules_ready,modules_total=excluded.modules_total,
    architecture_readiness=excluded.architecture_readiness,student_release_candidate=false,
    blocker_codes=excluded.blocker_codes,refreshed_at=now();
   rowsn:=rowsn+1;
 end loop;
 return jsonb_build_object('registered_courses',rowsn,'active_expansion','cl-8-basico','macroblock','v27.5-v27.9');
end $$;
revoke all on function public.refresh_v259_course_architecture() from public,anon,authenticated;

select public.refresh_v259_course_architecture();

commit;
